import assert from 'node:assert/strict';
import { execFileSync, spawn } from 'node:child_process';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g4-1/bot.mjs';
const { reserve } = await import(BOT);
const DAY = 24 * 60 * 60 * 1000;
const base = new Date('2026-10-23T10:00:00Z');
const at = (ms) => new Date(base.getTime() + ms);

const root = await fs.mkdtemp(path.join(os.tmpdir(), 'bot-state-'));
const stateDir = path.join(root, 'nested', 'state'); // missing parents on purpose
process.env.STATE_DIR = stateDir;

// 1. five allowed across mixed channels, sixth denied
const chans = ['sms', 'push', 'chat', 'sms', 'push'];
for (let i = 0; i < 5; i++) {
  const r = await reserve('alice', chans[i], at(i * 1000));
  assert.equal(r.allowed, true); assert.equal(r.retryAt, null);
}
const d = await reserve('alice', 'chat', at(6000));
assert.equal(d.allowed, false);
assert.equal(d.retryAt.getTime(), base.getTime() + DAY); // oldest send at t=0 + 24h
assert.match(d.reason, /5 proactive/);
console.log('reason:', d.reason);

// 2. denied call records nothing: still denied at same time
assert.equal((await reserve('alice', 'sms', at(7000))).allowed, false);

// 3. retryAt is exact: one ms before -> denied, at retryAt -> allowed
assert.equal((await reserve('alice', 'sms', new Date(d.retryAt.getTime() - 1))).allowed, false);
assert.equal((await reserve('alice', 'sms', d.retryAt)).allowed, true);

// 4. other customers are unaffected
assert.equal((await reserve('bob', 'push', at(8000))).allowed, true);

// 5. persistence across processes: child process sees the same state
const child = execFileSync(process.execPath, ['--input-type=module', '-e', `
  const { reserve } = await import(${JSON.stringify(BOT)});
  const r = await reserve('bob', 'sms', new Date(${base.getTime() + 9000}));
  console.log(JSON.stringify(r.allowed));`], { env: process.env }).toString().trim();
assert.equal(child, 'true');
for (let i = 0; i < 3; i++) await reserve('bob', 'sms', at(10000 + i));
assert.equal((await reserve('bob', 'sms', at(20000))).allowed, false);

// 6. window expiry: after 24h from the first send, a slot frees up
const later = at(DAY + 1);
const r6 = await reserve('bob', 'sms', later);
assert.equal(r6.allowed, true);

// 7. concurrency across 8 processes hammering the same customer at one instant
const N_PROC = 8, PER = 15;
const script = `
  const { reserve } = await import(${JSON.stringify(BOT)});
  let ok = 0;
  for (let i = 0; i < ${PER}; i++) {
    const r = await reserve('carol', ['sms','push','chat'][i % 3], new Date(${base.getTime() + 50 * DAY}));
    if (r.allowed) ok++;
  }
  console.log(ok);`;
const runs = Array.from({ length: N_PROC }, () => new Promise((resolve, reject) => {
  const p = spawn(process.execPath, ['--input-type=module', '-e', script], { env: process.env });
  let out = ''; let err = '';
  p.stdout.on('data', (c) => (out += c)); p.stderr.on('data', (c) => (err += c));
  p.on('exit', (code) => (code === 0 ? resolve(Number(out)) : reject(new Error(err))));
}));
const counts = await Promise.all(runs);
const total = counts.reduce((a, b) => a + b, 0);
console.log('allowed per process:', counts, 'total:', total);
assert.equal(total, 5);

// 8. stale lock from a crashed process is recovered, not blocking forever
const key = (await import('node:crypto')).createHash('sha256').update('dave').digest('hex');
await fs.mkdir(path.join(stateDir, 'locks', `${key}.lock`), { recursive: true });
const old = new Date(Date.now() - 60_000);
await fs.utimes(path.join(stateDir, 'locks', `${key}.lock`), old, old);
assert.equal((await reserve('dave', 'chat', at(0))).allowed, true);

// 9. invalid input is rejected
await assert.rejects(reserve('x', 'email', at(0)), TypeError);
await assert.rejects(reserve('x', 'sms', '2026-01-01'), TypeError);

await fs.rm(root, { recursive: true, force: true });
console.log('ALL TESTS PASSED');
EOF
cd /tmp/bot-test && timeout 120 node test.mjs
